class Solution {
    public List<Integer> spiralOrder(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        List<Integer> res = new ArrayList<>();
        boolean[][] flag = new boolean[m][n];

        int[] dx = {0,1,0,-1};
        int[] dy = {1,0,-1,0};
        for(int x=0,y=0,d=0,k=1;k<=m*n;k++){
            res.add(matrix[x][y]);
            flag[x][y] = true;
            int a = x + dx[d];
            int b = y + dy[d];
            if(a<0 || a>=m || b<0 || b>=n || flag[a][b]){
                d = (d+1)%4;
                a = x+dx[d];
                b = y+dy[d];
            }
            x = a;
            y = b;
        }
        return res;
    }
}
